from html.parser import HTMLParser
from urllib.request import Request, urlopen

class Paragraphs(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inside = False
        self.values = []
    def handle_starttag(self, tag, attrs):
        if tag == 'p':
            self.inside = True
            self.values.append('')
    def handle_endtag(self, tag):
        if tag == 'p':
            self.inside = False
    def handle_data(self, data):
        if self.inside:
            self.values[-1] += data

for name, headers in [
    ('custom', {'Cookie': 'theme=dark', 'Accept-Language': 'en-US;q=0.7, fr-CA;q=0.9, fr;q=0.8'}),
    ('default', {'Accept-Language': ''}),
]:
    parser = Paragraphs()
    parser.feed(urlopen(Request('http://localhost:3100', headers=headers)).read().decode())
    print(name, parser.values)
PY"

